using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

public class ConfigResource
{
    private static readonly Dictionary<string, object> _config = new()
    {
        ["appName"] = "McpHttpServer",
        ["version"] = "1.0.0",
        ["maxRetries"] = 3,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true
        }
    };

    [McpResource("config://app", Name = "AppConfig",
        Description = "Returns application configuration data")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(_config, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTool
{
    [McpServerTool(Name = "greet"),
     Description("Greets a user by name")]
    public static string Greet(string name)
    {
        return $"Hello, {name}! Welcome to the MCP HTTP server.";
    }
}

